using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Runtime.InteropServices;using System.Windows;using System.Windows.Controls;using System.Windows.Automation;using System.Windows.Media;using System.Windows.Media.Imaging;using System.Windows.Threading;using RingTimer;
class CardRefinementTests {
 static int checks;
 [DllImport("user32.dll")]static extern bool SetCursorPos(int x,int y);
 [DllImport("gdi32.dll")]static extern IntPtr CreateRectRgn(int l,int t,int r,int b);
 [DllImport("user32.dll")]static extern int GetWindowRgn(IntPtr window,IntPtr region);
 [DllImport("gdi32.dll")]static extern bool PtInRegion(IntPtr region,int x,int y);
 [DllImport("gdi32.dll")]static extern bool DeleteObject(IntPtr region);
 static bool LauncherSuppressed(Bubble bubble){IntPtr r=CreateRectRgn(0,0,0,0);try{return GetWindowRgn(bubble.Handle,r)==1;}finally{DeleteObject(r);}}
 static bool NativeContains(MenuWindow menu,Point point){IntPtr r=CreateRectRgn(0,0,0,0);try{GetWindowRgn(menu.Handle,r);double dpi=Native.ScaleFor(menu.Handle);return PtInRegion(r,(int)(point.X*dpi),(int)(point.Y*dpi));}finally{DeleteObject(r);}}
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);checks++;Console.WriteLine("PASS "+message);}
 static IEnumerable<T> All<T>(DependencyObject n) where T:DependencyObject{if(n is T)yield return (T)n;for(int i=0;i<VisualTreeHelper.GetChildrenCount(n);i++)foreach(var v in All<T>(VisualTreeHelper.GetChild(n,i)))yield return v;}
 static void Pump(int ms=80){var frame=new DispatcherFrame();var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(ms)};timer.Tick+=(s,e)=>{timer.Stop();frame.Continue=false;};timer.Start();Dispatcher.PushFrame(frame);}
 static byte[] GlyphPixels(MenuWindow menu,TextBlock label){var face=menu.CardPresenter.ContentVisual;double dpi=Native.ScaleFor(menu.Handle);var bitmap=new RenderTargetBitmap((int)Math.Ceiling(face.ActualWidth*dpi),(int)Math.Ceiling(face.ActualHeight*dpi),96*dpi,96*dpi,PixelFormats.Pbgra32);bitmap.Render(face);var at=label.TranslatePoint(new Point(),face);var crop=new Int32Rect((int)(at.X*dpi),(int)(at.Y*dpi),(int)(label.ActualWidth*dpi),(int)(label.ActualHeight*dpi));byte[] pixels=new byte[crop.Width*crop.Height*4];bitmap.CopyPixels(crop,pixels,crop.Width*4,0);return pixels;}
 static void CheckRenderedCard(string path){var bitmap=new BitmapImage(new Uri(Path.GetFullPath(path)));var pixels=new byte[bitmap.PixelWidth*bitmap.PixelHeight*4];bitmap.CopyPixels(pixels,bitmap.PixelWidth*4,0);foreach(double row in new[]{.25,.5,.75}){int y=(int)(bitmap.PixelHeight*row),painted=0;for(int x=bitmap.PixelWidth/4;x<bitmap.PixelWidth*3/4;x++)if(pixels[(y*bitmap.PixelWidth+x)*4+3]>32)painted++;Check(painted>bitmap.PixelWidth*.4,"projected card contains rendered content at height "+row);}}
 [STAThread]static int Main(string[] args){Native.SetProcessDPIAware();Native.POINT original;Native.GetCursorPos(out original);SetCursorPos(0,0);var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};MenuWindow menu=null;Bubble bubble=null;try{
 Theme.Apply(true,null,null,null);var timer=new TimerFeature(new TimerEngine(new TimerState(),()=>DateTime.UtcNow),()=>{});menu=new MenuWindow(new FeatureRegistry(timer,new StatsFeature(new StatsStore(null)),new ContextFeature()),()=>{},()=>{}){AnimationsEnabled=false,Left=-2000,Top=0};menu.Reveal();Pump();
 var close=All<Button>(menu).Single(b=>AutomationProperties.GetName(b)=="关闭小菜单");var center=close.TranslatePoint(new Point(close.ActualWidth/2,close.ActualHeight/2),menu.CardSurface);Check((center-new Point(menu.CardSurface.ActualWidth-Theme.MenuRadius,Theme.MenuRadius)).Length<.6,"close button and outer upper-right arc are concentric: "+center);
 menu.OpenFeature("timer");Pump(350);var label=All<TextBlock>(timer.Panel).Single(t=>AutomationProperties.GetName(t)=="剩余时间");var format=TextOptions.GetTextFormattingMode(label);var render=TextOptions.GetTextRenderingMode(label);double width=label.DesiredSize.Width;var glyphs=GlyphPixels(menu,label);menu.CardPresenter.Begin(new Point(180,200));Pump();Check(TextOptions.GetTextFormattingMode(label)==format&&TextOptions.GetTextRenderingMode(label)==render&&Math.Abs(label.DesiredSize.Width-width)<.1,"text rasterization and glyph layout stay fixed across tilt");var heldGlyphs=GlyphPixels(menu,label);double difference=glyphs.Zip(heldGlyphs,(a,b)=>Math.Abs(a-b)).Average();Check(difference<.25,"cached glyph pixels remain stable across presentation switch: "+difference.ToString("F3"));menu.CardPresenter.Release();Pump();
 bubble=new Bubble();bubble.Show();var area=System.Windows.Forms.Screen.PrimaryScreen.WorkingArea;bubble.MovePixels(area.Right-150,area.Bottom-100);menu.Launcher=bubble;menu.AnchorBounds=()=>bubble.PixelBounds;MenuApplication.PlacePanel(bubble,menu,-1);menu.RestoreCardContour();Pump();double dpi=Native.ScaleFor(menu.Handle);var bounds=menu.PixelBounds;var ring=bubble.PixelBounds;var ringCenter=new Point((ring.Left+ring.Width/2.0-bounds.Left)/dpi,(ring.Top+ring.Height/2.0-bounds.Top)/dpi);Check((ringCenter-new Point(menu.ActualWidth-8-Theme.MenuRadius,menu.ActualHeight-8-Theme.MenuRadius)).Length<1,"launcher and lower-right card corner are concentric");
 bubble.SetContext(new ContextUsage{Known=true,Used=61000,Capacity=100000});menu.CardPresenter.Begin(new Point(180,200));menu.CardPresenter.Move(new Point(340,50));Pump(350);Check(bubble.Opacity==1&&LauncherSuppressed(bubble),"independent launcher pixels are suppressed without resetting its compositor");Theme.Snapshot(menu,Path.Combine(args[0],"launcher-tilted.png"),dpi);CheckRenderedCard(Path.Combine(args[0],"launcher-tilted.png"));menu.CardPresenter.Release();Pump();Check(bubble.Opacity==1&&bubble.IsHitTestVisible,"launcher restored after gesture");
 menu.CardPresenter.Begin(new Point(180,200));menu.HideImmediately();Pump();Check(bubble.Opacity==1&&bubble.IsHitTestVisible,"launcher restored when menu hides during tilt");
 menu.Above=false;menu.ShowHome();menu.Reveal();MenuApplication.PlacePanel(bubble,menu,1);Pump();center=close.TranslatePoint(new Point(close.ActualWidth/2,close.ActualHeight/2),menu.CardSurface);Check((center-new Point(menu.CardSurface.ActualWidth-Theme.MenuRadius,menu.CardSurface.ActualHeight-Theme.MenuRadius)).Length<.6,"mirrored close button shares the lower corner arc center");
 for(int i=0;i<12;i++){menu.CardPresenter.Begin(new Point(180,200));menu.HideImmediately();menu.Reveal();}Pump();Check(bubble.Opacity==1&&bubble.IsHitTestVisible&&!menu.CardPresenter.IsPresenting,"rapid press and hide cycles preserve launcher and renderer lifetime");
 menu.Above=true;menu.Refresh();ring=bubble.PixelBounds;bubble.MovePixels(area.Right-ring.Width,area.Bottom-100);MenuApplication.PlacePanel(bubble,menu,-1);Pump();bounds=menu.PixelBounds;ring=bubble.PixelBounds;var outerRingPoint=new Point((ring.Right-2-bounds.Left)/dpi,(ring.Top+ring.Height/2.0-bounds.Top)/dpi);menu.CardPresenter.Begin(new Point(180,200));Pump();Check(NativeContains(menu,menu.CardPresenter.Projection.Project(outerRingPoint)),"launcher remains complete when card is clamped at right screen edge");menu.CardPresenter.Release();Pump();
 bubble.MovePixels(area.Left+70,area.Bottom-100);MenuApplication.PlacePanel(bubble,menu,-1);Pump();menu.CardPresenter.Begin(new Point(180,200));Pump();ring=bubble.PixelBounds;bubble.MovePixels(ring.Left+60,ring.Top);Pump();var copy=All<System.Windows.Shapes.Rectangle>(menu.CardPresenter.ContentVisual).Single(r=>r.Fill is VisualBrush);var copyCenter=copy.TranslatePoint(new Point(copy.ActualWidth/2,copy.ActualHeight/2),menu.CardPresenter.ContentVisual);ring=bubble.PixelBounds;bounds=menu.PixelBounds;var liveCenter=new Point((ring.Left+ring.Width/2.0-bounds.Left)/dpi,(ring.Top+ring.Height/2.0-bounds.Top)/dpi);Check((copyCenter-liveCenter).Length<1,"launcher copy follows relative anchor movement while card remains clamped");menu.CardPresenter.Release();Pump();
 foreach(string edge in new[]{"left","top","bottom"}){ring=bubble.PixelBounds;menu.Above=edge!="top";menu.Refresh();bubble.MovePixels(edge=="left"?area.Left:area.Right-150,edge=="top"?area.Top:edge=="bottom"?area.Bottom-ring.Height:area.Bottom-100);MenuApplication.PlacePanel(bubble,menu,menu.Above?-1:1);Pump();ring=bubble.PixelBounds;bounds=menu.PixelBounds;var point=new Point((ring.Left+(edge=="left"?2:ring.Width/2.0)-bounds.Left)/dpi,(ring.Top+(edge=="top"?2:edge=="bottom"?ring.Height-2:ring.Height/2.0)-bounds.Top)/dpi);menu.CardPresenter.Begin(new Point(180,200));menu.CardPresenter.Move(new Point(340,70));Pump(250);Check(NativeContains(menu,menu.CardPresenter.Projection.Project(point)),"tilted launcher remains complete at "+edge+" edge");menu.CardPresenter.Release();Pump();}
 Console.WriteLine(checks+" card refinement checks passed");return 0;
 }catch(Exception e){Console.WriteLine("FAIL "+e);return 1;}finally{SetCursorPos(original.X,original.Y);if(menu!=null){menu.Disposing=true;menu.Close();}if(bubble!=null)bubble.Close();app.Shutdown();}}
}
